import{_ as v,b as e,c as i,d as t,t as l,C as p,u as b}from"./index-I5uTs6b4.js";const u={class:"level-page"},c={class:"level-content"},n={class:"level-title"},q={__name:"Level11",props:{id:{type:String,required:!0}},setup(s){const d=b();function o(){sessionStorage.setItem("skipIntro","1"),d.push("/")}return(r,a)=>(e(),i("div",u,[t("button",{class:"back-btn",onClick:o},"← Back to Index"),t("div",c,[t("h1",n,"SI-"+l(s.id),1),a[0]||(a[0]=p('<p class="level-name" data-v-b7888571>&quot;影色舞&quot;</p><div class="section" data-v-b7888571><h2 data-v-b7888571>生存难度：等级 3</h2><div class="difficulty" data-v-b7888571><ul class="class-list" data-v-b7888571><li data-v-b7888571><span class="class-bullet safe" data-v-b7888571></span> 安全</li><li data-v-b7888571><span class="class-bullet unstable" data-v-b7888571></span> 不稳定</li><li data-v-b7888571><span class="class-bullet entity" data-v-b7888571></span> 少量实体威胁</li></ul></div></div><div class="section" data-v-b7888571><h2 data-v-b7888571>描述</h2><p data-v-b7888571>SI-11 表现为一栋带有后花园的三层别墅，季节被定格在仲夏，永远处于夜晚，别墅和后花园外，四周被黑暗笼罩，天空或是暗淡无光或是繁星点点。流浪者无法通过任何手段探索别墅和花园之外的地方。一旦进入就会被黑暗吞噬陷入昏迷，醒来后被传送回洋房二楼。虽然每个房间内都有灯，但是无法点亮。光源只有花园内的低矮花园灯，以及二楼书房内的绿色古典台灯。这些光源恒亮，无法关闭。</p><p data-v-b7888571>二楼书房内有一架金斯伯格钢琴，可被正常弹奏。该层级具有伪孤立效应，允许结伴进入，切入后却无法相遇。同时，结伴切入人数将决定 SI-11 内部分特殊实体的数量。</p></div><div class="section" data-v-b7888571><h2 data-v-b7888571>子层级：SI-11-1 &quot;十日河&quot;</h2><p data-v-b7888571>该子层级中是一条由繁星构成的笔直河流，河床布满人骨，河流最深处只能没过流浪者腰部。流浪者虽顺流而下，行进时却阻力重重，宛若逆流而上，面迎水流冲击。</p><p data-v-b7888571>流浪者进入时，便能看到&quot;十日河&quot;上空高悬的血红倒计时，上面将有为期十日的倒数。若是流浪者能在十日内走到&quot;十日河&quot;终点，便可切出到 SI-其他层级。若是未能完成，流浪者将沉入河底逝去，化为白骨，没于星河，直至时光终焉。</p><p data-v-b7888571><strong data-v-b7888571>切入方式：</strong>当 SI-11 内仅剩下流浪者自己的&quot;傍身之影&quot;时，流浪者的&quot;傍身之影&quot;将会向流浪者伸出手，带他穿过 SI-11 四周的黑暗，切入子层级&quot;十日河&quot;。</p><p data-v-b7888571><strong data-v-b7888571>切出方式：</strong>走到&quot;十日河&quot;尽头切出。</p><p data-v-b7888571><strong data-v-b7888571>特性：</strong>&quot;十日河&quot;会在流浪者前进的时候冲刷流浪者的意志，意志不坚定者可能会在途中被河流剥离血肉、人格、记忆，甚至被剥离独属于流浪者生命中的一段时间。</p></div><div class="section" data-v-b7888571><h2 data-v-b7888571>实体</h2><div class="entity-box" data-v-b7888571><p class="entity-name" data-v-b7888571>1. &quot;月光奏鸣&quot;</p><p class="entity-subtitle" data-v-b7888571>在星空暗淡无光时，月光洒落音符</p><p data-v-b7888571>该实体会替代正常出现的月光，其表现为月光亮度异常激增。同时月光中会有黑色音符下落，黑色音符会使接触到它的生物失去听觉。生物一旦被照射到，被照射部分将会血肉糜烂，只留下皑皑白骨。</p></div><div class="entity-box" data-v-b7888571><p class="entity-name" data-v-b7888571>2. &quot;春秋蝉蛊&quot;</p><p data-v-b7888571>在后花园出现的实体，当&quot;傍身之影&quot;出现在其附近时，发出蝉鸣，在数十秒鸣叫之后钻入地下，开始新一轮生命的周期。蝉鸣声中，天空迅速变换，星宿轮转，时间飞逝。可仲夏之夜，亘古不变，唯有蝉蛊破土鸣唱，复而沉眠，轻薄双翼，镌刻时间。</p></div><div class="entity-box" data-v-b7888571><p class="entity-name" data-v-b7888571>3. &quot;傍身之影&quot;</p><p data-v-b7888571>常态下无实体的虚影实体，其数量由结伴切入该层级的流浪者数量决定，且实体形态与切入的流浪者一一对应，仅在蝉鸣声中可被观测与触碰。鉴于孤立效应，流浪者会独自出现在该层级中，但是除了自己的&quot;傍身之影&quot;外，可以接触到同伴的&quot;傍身之影&quot;。流浪者将对可被观测接触状态下的属于自身的&quot;傍身之影&quot;有极其强的辨识能力。</p><p class="poetic" data-v-b7888571>你看不清它的面容，但能读懂它的天真。你知晓它是你，那个儿时的自己。它无法理解你血管流淌的焦虑，你无法拥抱儿时无忧脚步的轻盈。</p></div><div class="entity-box" data-v-b7888571><p class="entity-name" data-v-b7888571>4. &quot;四季虫歌&quot;</p><p data-v-b7888571>声音类实体，会在流浪者弹奏钢琴时出现。若是流浪者身边出现流浪者自己的&quot;傍身之影&quot;，&quot;四季虫歌&quot;不会出现。该实体会被真情流露的音乐吸引，出现后，时间流速加快，四季轮转，一年光阴白驹过隙，随后将流浪者送出该层级，并随机切入一个 SI 层级。</p></div></div><div class="section" data-v-b7888571><h2 data-v-b7888571>出口</h2><ul class="entry-list" data-v-b7888571><li data-v-b7888571>借助&quot;四季虫歌&quot;切出</li><li data-v-b7888571>在子层级&quot;十日河&quot;中切出</li></ul></div><div class="section" data-v-b7888571><h2 data-v-b7888571>有关实体特点</h2><p data-v-b7888571>属于流浪者自己的&quot;傍身之影&quot;若是被流浪者自己击杀，流浪者将会出现记忆缺失症状，也可能引发部分精神类疾病，严重程度不定。若是自己的&quot;傍身之影&quot;被其他流浪者杀死，流浪者自己也将一同死亡。</p></div><div class="epigraph" data-v-b7888571><p data-v-b7888571>人类怎样才能摆脱自己的影子？</p><p data-v-b7888571>人类怎样拒却自己的宿命？</p><p data-v-b7888571>人类怎样才能脱胎换骨？</p><p data-v-b7888571>人类怎样成为一个新的自我？</p><p data-v-b7888571>若是连自身都无法认清，又该向谁发问？</p><p data-v-b7888571>若是连自己的影子都无法摆脱，又怎样获得自由？</p></div>',8))])]))}},_=v(q,[["__scopeId","data-v-b7888571"]]);export{_ as default};
